            "p": "Нәтиже экраны осы күн сабағы үшін мына жолды көрсетеді: «Кең дала мен таулар. Оңай шайқалмайды, сүйенуге ыңғайлы, бірақ бір қабылдаған шешімін баяу өзгертеді.» Бұл жолдың төмендегі кестеге де, баллдарға да қатысы жоқ."
